import os
from typing import Dict, Any

from openai import OpenAI


def _extract_scores(result_text: str) -> Dict[str, float]:
    import json

    try:
        data = json.loads(result_text)
        if isinstance(data, dict):
            scores = data.get("category_scores", data)
            if isinstance(scores, dict):
                return {str(k): float(v) for k, v in scores.items() if isinstance(v, (int, float))}
    except Exception:
        pass
    return {}


def apply_category_thresholds(text: str, thresholds: Dict[str, float]) -> Dict[str, Any]:
    """
    Uses OpenAI's Moderation API to score text against safety categories and
    decides whether to allow it based on provided category thresholds.

    Args:
        text: Input text to evaluate.
        thresholds: Mapping of category name -> maximum allowed score.

    Returns:
        Dict with:
          - allow: bool
          - category_scores: dict
          - violated_thresholds: dict
          - model: str
    """
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

    moderation = client.moderations.create(
        model="omni-moderation-latest",
        input=text,
    )

    result = moderation.results[0]
    category_scores = dict(result.category_scores)

    violated = {}
    for category, threshold in thresholds.items():
        score = category_scores.get(category)
        if score is not None and score > threshold:
            violated[category] = {
                "score": score,
                "threshold": threshold,
            }

    allow = not result.flagged and not violated

    return {
        "allow": allow,
        "category_scores": category_scores,
        "violated_thresholds": violated,
        "model": "omni-moderation-latest",
    }
